import{_ as o,c as a,o as t,ag as r}from"./chunks/framework.CQuhCYrb.js";const b=JSON.parse('{"title":"Booting OS from USB","description":"","frontmatter":{"title":"Booting OS from USB"},"headers":[],"relativePath":"general/booting-os-from-usb.md","filePath":"general/booting-os-from-usb.md","lastUpdated":null}'),i={name:"general/booting-os-from-usb.md"};function s(n,e,l,u,c,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="booting-os-from-usb" tabindex="-1">Booting OS from USB <a class="header-anchor" href="#booting-os-from-usb" aria-label="Permalink to &quot;Booting OS from USB&quot;">​</a></h1><h2 id="flashing-linux-on-various-computer-brands" tabindex="-1">Flashing Linux on Various Computer Brands <a class="header-anchor" href="#flashing-linux-on-various-computer-brands" aria-label="Permalink to &quot;Flashing Linux on Various Computer Brands&quot;">​</a></h2><p>This page provides detailed instructions for installing Linux on computers from several top brands. It includes troubleshooting tips for common issues encountered during the installation process.</p><h3 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h3><ul><li><p><a href="#general-preparation">Preparation</a></p></li><li><p><a href="#brand-specific-instructions">Instructions</a></p><ul><li><a href="#key-table">Table for BIOS/UEFI Access</a></li><li>*** <em>HP</em>)(/hp)</li><li>*** [ASUS*)(/asus)</li><li>[* [Common Installation Issues and Troubleshooting*)(/common-installation-issues-and-troubleshooting)</li></ul></li><li><p><a href="#additional-resources">Resources</a></p></li></ul><h3 id="general-preparation" tabindex="-1">General Preparation <a class="header-anchor" href="#general-preparation" aria-label="Permalink to &quot;General Preparation&quot;">​</a></h3><p>Before flashing Linux, ensure the following steps are completed:</p><ul><li><p><strong>Backup Data</strong>: Always back up important data to an external drive or cloud storage.</p></li><li><p><strong>Create a Bootable USB Drive</strong>: Use tools like Rufus or Balena Etcher to create a Linux bootable USB drive. <a href="#bootable-usb">Here</a></p></li><li><p><strong>Update BIOS/UEFI</strong>: Ensure your BIOS/UEFI firmware is up-to-date to avoid compatibility issues.</p></li></ul><h3 id="brand-specific-instructions" tabindex="-1">Brand-Specific Instructions <a class="header-anchor" href="#brand-specific-instructions" aria-label="Permalink to &quot;Brand-Specific Instructions&quot;">​</a></h3><h3 id="key-table-for-bios-uefi-access" tabindex="-1">Key Table for BIOS/UEFI Access <a class="header-anchor" href="#key-table-for-bios-uefi-access" aria-label="Permalink to &quot;Key Table for BIOS/UEFI Access&quot;">​</a></h3><p>The table below summarizes the key combinations to access BIOS/UEFI for different computer manufacturers.</p><table tabindex="0"><thead><tr><th>Manufacturer</th><th>Keys</th><th>Comments</th></tr></thead><tbody><tr><td>Dell</td><td>F2</td><td>Press during boot. Disable &quot;Secure Boot&quot; under Security tab</td></tr><tr><td>HP</td><td>F10</td><td>Press as computer starts. Enable &quot;Legacy Support&quot; for USB boot</td></tr><tr><td>Lenovo</td><td>F1 or F2</td><td>Tap when Lenovo logo appears. Change from UEFI to Legacy if needed</td></tr><tr><td>ASUS</td><td>F2 or Delete</td><td>Press when ASUS logo shows. Adjust Boot Priority to select USB first</td></tr><tr><td>Acer</td><td>F2</td><td>Press as Acer logo appears. Set USB as first boot device</td></tr></tbody></table><h3 id="dell" tabindex="-1">Dell <a class="header-anchor" href="#dell" aria-label="Permalink to &quot;Dell&quot;">​</a></h3><h4 id="accessing-bios-uefi" tabindex="-1">Accessing BIOS/UEFI <a class="header-anchor" href="#accessing-bios-uefi" aria-label="Permalink to &quot;Accessing BIOS/UEFI&quot;">​</a></h4><ul><li><p>Restart your Dell computer and press <strong>F2</strong> during boot to enter BIOS settings.</p></li><li><p>Navigate to the “Boot” tab and change the boot order to prioritize the USB drive.</p></li></ul><h4 id="secure-boot" tabindex="-1">Secure Boot <a class="header-anchor" href="#secure-boot" aria-label="Permalink to &quot;Secure Boot&quot;">​</a></h4><ul><li>Disable “Secure Boot” to allow Linux to install, which is typically found under the “Security” tab.</li></ul><h3 id="hp" tabindex="-1">HP <a class="header-anchor" href="#hp" aria-label="Permalink to &quot;HP&quot;">​</a></h3><h4 id="accessing-bios-uefi-1" tabindex="-1">Accessing BIOS/UEFI <a class="header-anchor" href="#accessing-bios-uefi-1" aria-label="Permalink to &quot;Accessing BIOS/UEFI&quot;">​</a></h4><ul><li>Press <strong>F10</strong> as your HP computer starts to enter BIOS settings.</li></ul><h4 id="legacy-support" tabindex="-1">Legacy Support <a class="header-anchor" href="#legacy-support" aria-label="Permalink to &quot;Legacy Support&quot;">​</a></h4><ul><li>In BIOS, enable “Legacy Support” to allow booting from USB.</li></ul><h3 id="lenovo" tabindex="-1">Lenovo <a class="header-anchor" href="#lenovo" aria-label="Permalink to &quot;Lenovo&quot;">​</a></h3><h4 id="accessing-bios-uefi-2" tabindex="-1">Accessing BIOS/UEFI <a class="header-anchor" href="#accessing-bios-uefi-2" aria-label="Permalink to &quot;Accessing BIOS/UEFI&quot;">​</a></h4><ul><li>Tap the <strong>F1</strong> or <strong>F2</strong> key when the Lenovo logo appears.</li></ul><h4 id="uefi-legacy-boot" tabindex="-1">UEFI/Legacy Boot <a class="header-anchor" href="#uefi-legacy-boot" aria-label="Permalink to &quot;UEFI/Legacy Boot&quot;">​</a></h4><ul><li>Change the boot mode from UEFI to Legacy if facing issues with the USB boot.</li></ul><h3 id="asus" tabindex="-1">ASUS <a class="header-anchor" href="#asus" aria-label="Permalink to &quot;ASUS&quot;">​</a></h3><h4 id="accessing-bios-uefi-3" tabindex="-1">Accessing BIOS/UEFI <a class="header-anchor" href="#accessing-bios-uefi-3" aria-label="Permalink to &quot;Accessing BIOS/UEFI&quot;">​</a></h4><ul><li>Press <strong>F2</strong> or <strong>Delete</strong> when the ASUS logo shows.</li></ul><h4 id="boot-priority" tabindex="-1">Boot Priority <a class="header-anchor" href="#boot-priority" aria-label="Permalink to &quot;Boot Priority&quot;">​</a></h4><ul><li>Adjust the Boot Priority to ensure the USB drive is selected first.</li></ul><h3 id="acer" tabindex="-1">Acer <a class="header-anchor" href="#acer" aria-label="Permalink to &quot;Acer&quot;">​</a></h3><h4 id="accessing-bios-uefi-4" tabindex="-1">Accessing BIOS/UEFI <a class="header-anchor" href="#accessing-bios-uefi-4" aria-label="Permalink to &quot;Accessing BIOS/UEFI&quot;">​</a></h4><ul><li>Press the <strong>F2</strong> key as soon as the Acer logo appears.</li></ul><h4 id="setting-boot-order" tabindex="-1">Setting Boot Order <a class="header-anchor" href="#setting-boot-order" aria-label="Permalink to &quot;Setting Boot Order&quot;">​</a></h4><ul><li>Prioritize the USB drive in the boot sequence to start the Linux installation.</li></ul><h3 id="common-installation-issues-and-troubleshooting" tabindex="-1">Common Installation Issues and Troubleshooting <a class="header-anchor" href="#common-installation-issues-and-troubleshooting" aria-label="Permalink to &quot;Common Installation Issues and Troubleshooting&quot;">​</a></h3><h3 id="issue-1-system-stuck-on-brand-logo" tabindex="-1">Issue 1: System Stuck on Brand Logo <a class="header-anchor" href="#issue-1-system-stuck-on-brand-logo" aria-label="Permalink to &quot;Issue 1: System Stuck on Brand Logo&quot;">​</a></h3><ul><li><strong>Solution</strong>: Check if “Secure Boot” is disabled in BIOS settings.</li></ul><h3 id="issue-2-no-bootable-device-found" tabindex="-1">Issue 2: No Bootable Device Found <a class="header-anchor" href="#issue-2-no-bootable-device-found" aria-label="Permalink to &quot;Issue 2: No Bootable Device Found&quot;">​</a></h3><ul><li><strong>Solution</strong>: Switch the boot mode from UEFI to Legacy or vice versa, depending on your system setup.</li></ul><h3 id="issue-3-black-screen-after-booting-from-usb" tabindex="-1">Issue 3: Black Screen After Booting from USB <a class="header-anchor" href="#issue-3-black-screen-after-booting-from-usb" aria-label="Permalink to &quot;Issue 3: Black Screen After Booting from USB&quot;">​</a></h3><ul><li><strong>Solution</strong>: Modify the Linux boot parameters by adding <code>nomodeset</code> before booting.</li></ul><h3 id="issue-4-installation-freezes" tabindex="-1">Issue 4: Installation Freezes <a class="header-anchor" href="#issue-4-installation-freezes" aria-label="Permalink to &quot;Issue 4: Installation Freezes&quot;">​</a></h3><ul><li><strong>Solution</strong>: Try using a different USB port or re-creating the bootable USB drive.</li></ul><h3 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h3><ul><li><p><a href="https://ubuntu.com/tutorials/install-ubuntu-desktop#1-overview" target="_blank" rel="noreferrer">Ubuntu Installation Guide</a></p></li><li><p><a href="https://linuxmint-installation-guide.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">Linux Mint Installation Documentation</a></p></li></ul><p>[Installation] [Configuration]</p>',49)])])}const g=o(i,[["render",s]]);export{b as __pageData,g as default};
